class Solution {
public:
    string simplifyPath(string path) {
        string result;
        result.push_back('/');
        int n = (int)path.size();
        int i = 1;
        while (i < n) {
            while (i < n && path[i] == '/') i++;
            if (i >= n) break;
            int start = i;
            while (i < n && path[i] != '/') i++;
            int len = i - start;
            if (len == 2 && path[start] == '.' && path[start + 1] == '.') {
                if (result.size() > 1) {
                    result.pop_back();
                    while (result.size() > 1 && result.back() != '/') {
                        result.pop_back();
                    }
                }
            } else if (len == 1 && path[start] == '.') {
                // current directory, skip
            } else {
                for (int j = start; j < i; j++) {
                    result.push_back(path[j]);
                }
                result.push_back('/');
            }
        }
        if (result.size() > 1) {
            result.pop_back();
        }
        return result;
    }
};
